const modulOf=u=>u.modul.split("›")[0].trim();
const tahunOf=u=>(u.mulai||"").slice(0,4)||"2026";
function kompLong(k,m){return({"Tim PMO Kemenkeu":"Project Management Office Kementerian Keuangan","Tim CMO Kemenkeu":"Change Management Office Kementerian Keuangan","Tim PMO Unit":"Project Management Office pada unit Eselon I dan unit non-Eselon","Tim CMO Unit":"Change Management Office pada unit Eselon I dan unit non-Eselon","Tim Pengelola Komunikasi dan Pelatihan":"Tim Pengelola Komunikasi dan Pelatihan "+m})[k]||k}
function kompShort(k,m){return({"Tim PMO Unit":"PMO pada unit Eselon I dan unit non-Eselon","Tim CMO Unit":"CMO pada unit Eselon I dan unit non-Eselon","Tim Pengelola Komunikasi dan Pelatihan":"Tim Pengelola Komunikasi dan Pelatihan "+m})[k]||k}
function kompLamp(k,m){const x=({"Tim PMO Kemenkeu":"Tim PMO Kementerian Keuangan","Tim CMO Kemenkeu":"Tim CMO Kementerian Keuangan","Tim PMO Unit":"Tim PMO pada Unit Eselon I dan Unit Non-Eselon","Tim CMO Unit":"Tim CMO pada Unit Eselon I dan Unit Non-Eselon","Tim Pengelola Komunikasi dan Pelatihan":"Tim Pengelola Komunikasi dan Pelatihan "+m})[k]||(/^(Tim|Sekretariat)\b/.test(k)?k:"Tim "+k);return x.toUpperCase()}
let KTYPE={};
const isUnitKomp=k=>KTYPE[k]?KTYPE[k]==="unit":/Unit Eselon I|^Tim (PMO|CMO) Unit$/.test(k);
const isPimpinan=k=>KTYPE[k]?KTYPE[k]==="pimpinan":/^(Ketua|Wakil Ketua)( [IVX]+)?$/.test(k);
const joinDan=(arr,sep="dan")=>arr.length<2?arr.join(""):arr.slice(0,-1).join(", ")+(arr.length>2?",":"")+` ${sep} `+arr[arr.length-1];
const listSuffix=(arr,lastEnd)=>arr.map((t,i)=>{t=t.replace(/[;,.]\s*(dan)?\s*$/,"");return t+(i===arr.length-1?lastEnd:i===arr.length-2?"; dan":";")});

function buildSK(u){
 const m=modulOf(u),P=u.penetap,PU=P.toUpperCase(),th=tahunOf(u);
 const pendek=P.startsWith("Kepala Badan")?"Kepala Badan":P.startsWith("Menteri")?"Menteri":P.startsWith("Direktur Jenderal")?"Direktur Jenderal":P.startsWith("Sekretaris Jenderal")?"Sekretaris Jenderal":"ini";
 const R=s=>s.replace(/\[Modul\]/g,m).replace(/\[Penetap\]/g,P);
 const komp=u.komp.filter(k=>u.anggota.some(a=>a.ko===k));
 const huruf=k=>String.fromCharCode(97+komp.indexOf(k));
 const D=[];
 D.push({kind:"kesatu",intro:`Membentuk ${u.nama}, yang selanjutnya disebut Tim, yang terdiri atas:`,items:listSuffix(komp.map(k=>kompLong(k,m)),","),outro:`dengan susunan keanggotaan sebagaimana tercantum dalam Lampiran yang merupakan bagian tidak terpisahkan dari Keputusan ${pendek} ini.`});
 if(komp.some(k=>/^(PMO|CMO)/.test(k)))D.push({kind:"list",intro:"Tim sebagaimana dimaksud dalam Diktum KESATU menyelenggarakan fungsi:",items:["Project Management Office yang selanjutnya disebut PMO, berupa perencanaan, pengendalian, pemantauan, pengelolaan risiko dan isu, serta pelaporan proyek; dan","Change Management Office yang selanjutnya disebut CMO, berupa pengelolaan aspek manusia dan organisasi dalam pelaksanaan perubahan yang meliputi kesiapan, komunikasi, pembelajaran, pelibatan pemangku kepentingan, dan adopsi perubahan."]});
 let ketuaIdx=-1,ketuaT=[];
 komp.forEach(k=>{const t=(u.tugas[k]||[]).filter(x=>x.on&&x.t.trim()).map(x=>R(x.t.trim()));if(!t.length)return;
  if(/^Ketua( [IVX]+)?$/.test(k)&&ketuaIdx<0){ketuaIdx=D.length;ketuaT=t}
  D.push({kind:"list",intro:`${kompShort(k,m)} sebagaimana dimaksud dalam Diktum KESATU huruf ${huruf(k)} mempunyai tugas dan tanggung jawab:`,items:listSuffix(t,".")})});
 D.push({kind:"list",intro:"Dalam melaksanakan tugas dan tanggung jawabnya, Tim sebagaimana dimaksud dalam Diktum KESATU dapat:",items:["melakukan koordinasi untuk memperoleh data, informasi, bahan, dan dukungan yang diperlukan dari unit terkait;","menyelenggarakan forum koordinasi, pemantauan, evaluasi, komunikasi, dan pembelajaran;","melakukan asesmen kesiapan dan pengukuran tingkat adopsi sesuai dengan kebutuhan; dan","melakukan eskalasi isu secara berjenjang serta mendokumentasikan hasil koordinasi, arahan, dan keputusan."]});
 const ord=i=>ORD[i];
 const kD=ketuaIdx>=0?ord(ketuaIdx):"KETIGA";
 const hEval=String.fromCharCode(97+Math.max(0,ketuaT.findIndex(t=>/evaluasi berkala/.test(t)))),hLap=String.fromCharCode(97+Math.max(0,ketuaT.findIndex(t=>/menyampaikan laporan/.test(t))));
 const bantu=["Wakil Ketua I","Wakil Ketua II","Tim PMO Kemenkeu","Tim CMO Kemenkeu"].filter(k=>komp.includes(k));
 const KTS=komp.filter(k=>/^Ketua( [IVX]+)?$/.test(k));D.push({kind:"eval",text:`${KTS.length>1?joinDan(KTS,"dan"):"Ketua"} melakukan evaluasi berkala sebagaimana dimaksud dalam Diktum ${kD} huruf ${hEval} paling sedikit 1 (satu) kali dalam 3 (tiga) bulan${bantu.length?` dan dapat dibantu oleh ${joinDan(bantu,"dan/atau")}`:""} yang hasilnya digunakan sebagai dasar penetapan tindak lanjut, penyesuaian strategi pelaksanaan, dan/atau perubahan keanggotaan Tim.`});
 const lapIdx=D.length;
 D.push({kind:"list",intro:`Laporan pelaksanaan tugas Tim sebagaimana dimaksud dalam Diktum ${kD} huruf ${hLap} disampaikan:`,items:["secara berkala paling sedikit 1 (satu) kali dalam 3 (tiga) bulan;","sewaktu-waktu apabila diperlukan; dan","paling lambat pada saat berakhirnya masa kerja Tim."]});
 D.push({kind:"list",intro:`Laporan sebagaimana dimaksud dalam Diktum ${ord(lapIdx)} paling sedikit memuat:`,items:["capaian kegiatan dan realisasi jadwal;","hasil pengukuran kesiapan dan tingkat adopsi;","risiko, isu, resistensi, dan umpan balik;","keputusan, rekomendasi, dan tindak lanjut; dan","kebutuhan dukungan."]});
 D.push({kind:"text",text:`Masa kerja Tim terhitung sejak tanggal ${fmtD(u.mulai)} sampai dengan tanggal ${fmtD(u.selesai)}.`});
 D.push({kind:"text",text:`Dalam hal terdapat perubahan pada keanggotaan Tim sebagaimana tercantum dalam Lampiran Keputusan ${pendek} ini, perubahan ditetapkan oleh ${u.pengubah||"Kepala Pusat Manajemen Transformasi dan Perubahan"} untuk dan atas nama ${P}.`});
 D.push({kind:"text",text:"Kepada setiap anggota Tim tidak diberikan honorarium."});
 D.push({kind:"text",text:`Segala biaya yang timbul sebagai akibat ditetapkannya Keputusan ${pendek} ini dibebankan pada Daftar Isian Pelaksanaan Anggaran ${u.dipa}.`});
 const surut=u.surut||(u.mulai&&new Date(u.mulai)<new Date());
 D.push({kind:"berlaku",text:`Keputusan ${pendek} ini mulai berlaku pada tanggal ditetapkan${surut?` dan berlaku surut sejak tanggal ${fmtD(u.mulai)}`:""}.`});
 D.forEach((d,i)=>d.label=ord(i));
 // lampiran
 const cellNama=(a,withSatker)=>a.jenis==="nama"?`${a.nama},\n${a.nip}\n${a.satker}`:(withSatker&&a.satker&&!a.jab.includes(a.satker)?`${a.jab},\n${a.satker}`:a.jab);
 const S=[];const pimp=komp.filter(isPimpinan);
 if(pimp.length)S.push({title:pimp.length>1?"KETUA DAN WAKIL KETUA":"KETUA",type:"A",rows:pimp.flatMap(k=>u.anggota.filter(a=>a.ko===k).map(a=>[cellNama(a,false),a.es1,k]))});
 komp.filter(k=>!isPimpinan(k)).forEach(k=>{const L=u.anggota.filter(a=>a.ko===k);
  if(isUnitKomp(k))S.push({title:kompLamp(k,m),type:"C",rows:L.map(a=>[cellNama(a,true),a.es1])});
  else{const groups=[];L.forEach(a=>{let g=groups.find(g=>g.es1===a.es1);if(!g)groups.push(g={es1:a.es1,rows:[]});g.rows.push([cellNama(a,true),a.ked])});S.push({title:kompLamp(k,m),type:"B",groups})}});
 S.forEach((s,i)=>s.title=`${String.fromCharCode(65+i)}. ${s.title}`);
 const judul=`PEMBENTUKAN ${u.nama.toUpperCase()}`;
 const signLine=u.an?`a.n. ${PU}\n${u.an.toUpperCase()}`:PU;
 return{P,PU,pendek,ttd:u.ttd||"",judul,signLine,tempat:u.tempat||"Jakarta",tembusan:u.tembusan||null,namaUp:u.nama.toUpperCase(),
  menimbang:[`bahwa untuk mendukung pelaksanaan tugas dan fungsi Kementerian Keuangan melalui transformasi digital yang efektif, efisien, dan akuntabel, diperlukan implementasi ${m} pada Program Transformasi ${u.program} Tahun ${th}${u.tujuan?" "+u.tujuan:""};`,
   `bahwa guna mendukung efektivitas implementasi ${m} sebagaimana dimaksud dalam huruf a, perlu dibentuk tim kerja${u.lingkup?" "+u.lingkup:""};`,
   `bahwa berdasarkan pertimbangan sebagaimana dimaksud dalam huruf a dan huruf b, perlu menetapkan Keputusan ${P} tentang Pembentukan ${u.nama};`],
  menetapkan:`KEPUTUSAN ${PU} TENTANG PEMBENTUKAN ${u.nama.toUpperCase()}`,diktum:D,lamp:S}}

