function skHTML(u){const M=buildSK(u);const ph=v=>`<span class="ph-v">${v}</span>`;
 const al=a=>`<ol class="al">${a.map(x=>`<li>${itl(x)}</li>`).join("")}</ol>`;
 const dk=M.diktum.map(d=>`<tr><td class="k">${d.label}</td><td class="c">:</td><td>${d.text?itl(d.text):`${itl(d.intro)}${al(d.items)}${d.outro?itl(d.outro):""}`}</td></tr>`).join("");
 const lt=s=>{if(s.type==="A")return`<table class="lamp"><tr><th style="width:36px">No.</th><th>Nama/Jabatan</th><th style="width:30%">Satuan Kerja</th><th style="width:90px">Kedudukan</th></tr>${s.rows.map((r,i)=>`<tr><td>${i+1}</td><td>${itl(r[0])}</td><td>${esc(r[1])}</td><td style="text-align:center">${esc(r[2])}</td></tr>`).join("")}</table>`;
  if(s.type==="C")return`<table class="lamp"><tr><th style="width:36px">No.</th><th>Nama/Jabatan</th><th style="width:34%">Satuan Kerja</th></tr>${s.rows.map((r,i)=>`<tr><td>${i+1}</td><td>${itl(r[0])}</td><td style="text-align:center">${esc(r[1])}</td></tr>`).join("")}</table>`;
  let n=0;return`<table class="lamp"><tr><th style="width:36px">No.</th><th>Nama/Jabatan</th><th style="width:90px">Kedudukan</th></tr>${s.groups.map(g=>`<tr><td colspan="3"><b>${esc(g.es1)}</b></td></tr>${g.rows.map(r=>`<tr><td>${++n}</td><td>${itl(r[0])}</td><td style="text-align:center">${esc(r[1])}</td></tr>`).join("")}`).join("")}</table>`};
 return`<div class="paper" id="skDoc">
  <div class="ttl">KEPUTUSAN ${esc(M.PU)}<br>NOMOR ${ph("[@NomorND]")}<br>TENTANG<br>${itl(M.judul)}</div>
  <p style="margin:18px 0 10px;font-weight:700">${esc(M.PU)},</p>
  <table class="dk">
   <tr><td class="k">Menimbang</td><td class="c">:</td><td>${al(M.menimbang)}</td></tr>
   <tr><td class="k">Mengingat</td><td class="c">:</td><td><ol>${MENGINGAT.map(x=>`<li>${itl(x)}</li>`).join("")}</ol></td></tr>
   <tr><td colspan="3" style="padding:12px 0 6px 40%">MEMUTUSKAN:</td></tr>
   <tr><td class="k">Menetapkan</td><td class="c">:</td><td>${itl(M.menetapkan)}</td></tr>
   ${dk}
  </table>
  ${M.tembusan?`<div style="margin:12px 0 0 150px">Keputusan ${M.pendek} ini disampaikan kepada:<ol>${M.tembusan.map(x=>`<li>${itl(x)}</li>`).join("")}</ol></div>`:""}<div class="sign">Ditetapkan di ${esc(M.tempat)}<br>pada tanggal ${ph("[@TanggalND]")}<br><br>${itl(M.signLine)}<br><br>Ditandatangani secara elektronik<br>${esc(M.ttd)}</div>
 </div>
 <div class="paper">
  <div style="margin-left:42%;font-size:12.5px">LAMPIRAN<br>KEPUTUSAN ${esc(M.PU)}<br>NOMOR ${ph("[@NomorND]")}<br>TENTANG<br>${itl(M.judul)}</div>
  <p class="ttl" style="margin-top:16px">SUSUNAN DAN KEANGGOTAAN<br>${itl(M.namaUp)}</p>
  ${M.lamp.map(s=>`<p style="margin:10px 0 2px"><b>${itl(s.title)}</b></p>${lt(s)}`).join("")}
  <div class="sign">${itl(M.signLine)},<br><br>Ditandatangani secara elektronik<br>${esc(M.ttd)}</div>
 </div>`}

/* ---------- Word: isi dimasukkan ke cetakan KEP asli ---------- */
const WNS="http://schemas.openxmlformats.org/wordprocessingml/2006/main",XNS="http://www.w3.org/XML/1998/namespace";
const kids=(el,n)=>[...el.childNodes].filter(x=>x.nodeType===1&&(!n||x.localName===n));
const deep=(el,n)=>[...el.getElementsByTagNameNS(WNS,n)];
const ptext=p=>deep(p,"t").map(t=>t.textContent).join("").replace(/\s+/g," ").trim();
function baseRPr(p){const d=p.ownerDocument;let rp=null;for(const r of deep(p,"r")){const x=kids(r,"rPr")[0];if(deep(r,"t").length){rp=x;break}}
 if(!rp){const pp=kids(p,"pPr")[0];rp=pp&&kids(pp,"rPr")[0]}
 rp=rp?rp.cloneNode(true):d.createElementNS(WNS,"w:rPr");["highlight","i","iCs","rStyle"].forEach(t=>kids(rp,t).forEach(n=>rp.removeChild(n)));return rp}
function addItal(rp){const d=rp.ownerDocument;const before=kids(rp).find(n=>!["rStyle","rFonts","b","bCs"].includes(n.localName));
 ["i","iCs"].forEach(t=>{const e=d.createElementNS(WNS,"w:"+t);before?rp.insertBefore(e,before):rp.appendChild(e)})}
function setText(p,text){const d=p.ownerDocument,rp=baseRPr(p);kids(p).forEach(n=>{if(n.localName!=="pPr")p.removeChild(n)});
 const lines=String(text).split("\n");
 lines.forEach((ln,li)=>{const parts=ln.split(ITAL);parts.forEach((seg,si)=>{if(!seg&&!(li>0&&si===0))return;
  const r=d.createElementNS(WNS,"w:r"),rr=rp.cloneNode(true);if(si%2===1)addItal(rr);r.appendChild(rr);
  if(li>0&&si===0)r.appendChild(d.createElementNS(WNS,"w:br"));
  if(seg){const t=d.createElementNS(WNS,"w:t");t.setAttributeNS(XNS,"xml:space","preserve");t.textContent=seg;r.appendChild(t)}p.appendChild(r)})})}
const norm=s=>String(s).replace(/\s+/g," ").trim();
function setIf(p,text){if(norm(ptext(p))!==norm(text.replace(/\n/g,"")))setText(p,text)}
function mkP(proto,text,numId){const p=proto.cloneNode(true);if(numId){const n=deep(p,"numId")[0];if(n)n.setAttributeNS(WNS,"w:val",String(numId))}setText(p,text);return p}
function setCell(tc,text){const ps=kids(tc,"p");ps.slice(1).forEach(x=>tc.removeChild(x));setText(ps[0],text)}
function wrapTitle(s,max=52){const chunks=s.split(/ (?=IMPLEMENTASI |PROGRAM |TAHUN \d)/);const out=[];
 chunks.forEach(c=>{let line="";c.split(" ").forEach(w=>{if(line&&(line+" "+w).length>max){out.push(line);line=w}else line=line?line+" "+w:w});if(line)out.push(line)});return out}
function fitParas(container,ps,lines){ // isi baris ke paragraf yang ada, tambah/kurangi sesuai jumlah baris
 while(ps.length<lines.length){const c=ps[ps.length-1].cloneNode(true);ps[ps.length-1].after(c);ps.push(c)}
 ps.slice(lines.length).forEach(x=>x.parentNode.removeChild(x));lines.forEach((l,i)=>setIf(ps[i],l))}
function b64u8(b){const s=atob(b),a=new Uint8Array(s.length);for(let i=0;i<s.length;i++)a[i]=s.charCodeAt(i);return a}

async function buildDocx(u){
 if(typeof JSZip==="undefined")throw new Error("Pustaka JSZip belum termuat");
 const M=buildSK(u),zip=await JSZip.loadAsync(b64u8(KEP_B64));
 const doc=new DOMParser().parseFromString(await zip.file("word/document.xml").async("string"),"application/xml");
 let numXml=await zip.file("word/numbering.xml").async("string");
 const absOf=id=>(numXml.match(new RegExp(`<w:num w:numId="${id}"[^>]*>\\s*<w:abstractNumId w:val="(\\d+)"`))||[])[1];
 let nextNum=Math.max(...[...numXml.matchAll(/<w:num w:numId="(\d+)"/g)].map(x=>+x[1]))+1;const newNums=[];
 const newList=abs=>{const id=nextNum++;newNums.push(`<w:num w:numId="${id}"><w:abstractNumId w:val="${abs}"/><w:lvlOverride w:ilvl="0"><w:startOverride w:val="1"/></w:lvlOverride></w:num>`);return id};
 const body=deep(doc,"body")[0],ch=kids(body);
 const [hdr,main]=[ch[1],ch[3]];
 // kop judul
 const hr=kids(hdr,"tr"),h0=kids(kids(hr[0],"tc")[0],"p"),h1=kids(kids(hr[1],"tc")[0],"p");
 const kepLines=norm("KEPUTUSAN "+M.PU)===norm(ptext(h0[0])+" "+ptext(h0[1]))?[ptext(h0[0]),ptext(h0[1])]:wrapTitle("KEPUTUSAN "+M.PU,46);
 fitParas(null,h0.slice(0,2),kepLines);
 fitParas(null,h1,wrapTitle(M.judul));
 setIf(kids(kids(hr[3],"tc")[0],"p")[0],M.P+",");
 // tabel batang tubuh
 const rows=kids(main,"tr"),c2=r=>kids(r,"tc")[2],ps=r=>kids(c2(r),"p");
 const mn=ps(rows[0]);fitParas(null,mn,M.menimbang);
 setIf(ps(rows[3])[0],M.menetapkan);
 const P5=ps(rows[5]),kIntro=P5[0],kItem=P5[1],kOutro=P5[P5.length-1];
 const lIntro=ps(rows[8])[0],lItem=ps(rows[7])[1];
 const rList=rows[7],rText=rows[19],rEval=rows[16],rBerl=rows[23],rKes=rows[5];
 const absK=absOf(deep(kItem,"numId")[0].getAttributeNS(WNS,"val")||deep(kItem,"numId")[0].getAttribute("w:val")),absL=absOf(deep(lItem,"numId")[0].getAttribute("w:val"));
 const protos={rList:rList.cloneNode(true),rText:rText.cloneNode(true),rEval:rEval.cloneNode(true),rBerl:rBerl.cloneNode(true),rKes:rKes.cloneNode(true)};
 const kI=kIntro.cloneNode(true),kIt=kItem.cloneNode(true),kO=kOutro.cloneNode(true),lI=lIntro.cloneNode(true),lIt=lItem.cloneNode(true);
 const anchor=rows[24];rows.slice(5,24).forEach(r=>main.removeChild(r));
 M.diktum.forEach(d=>{let tr;
  if(d.kind==="kesatu"||d.kind==="list"){tr=(d.kind==="kesatu"?protos.rKes:protos.rList).cloneNode(true);const cell=kids(tr,"tc")[2];kids(cell,"p").forEach(p=>cell.removeChild(p));
   const nid=newList(d.kind==="kesatu"?absK:absL);
   cell.appendChild(mkP(d.kind==="kesatu"?kI:lI,d.intro));d.items.forEach(t=>cell.appendChild(mkP(d.kind==="kesatu"?kIt:lIt,t,nid)));if(d.outro)cell.appendChild(mkP(kO,d.outro))}
  else{tr=(d.kind==="eval"?protos.rEval:d.kind==="berlaku"?protos.rBerl:protos.rText).cloneNode(true);setCell(kids(tr,"tc")[2],d.text)}
  setCell(kids(tr,"tc")[0],d.label);main.insertBefore(tr,anchor)});
 const rows2=kids(main,"tr"),L=rows2.length; // baris tembusan & tanda tangan di akhir tabel
 setIf(ps(rows2[L-7])[0],`Keputusan ${M.pendek} ini disampaikan kepada:`);
 setIf(kids(kids(rows2[L-4],"tc")[1],"p")[0],M.signLine);
 setIf(ps(rows2[L-5])[0],"Ditetapkan di "+M.tempat);
 if(M.tembusan){const tc=c2(rows2[L-7]),tp=kids(tc,"p");if(norm(tp.slice(1).map(ptext).join("|"))!==norm(M.tembusan.join("|"))){const pr=tp[1].cloneNode(true);tp.slice(1).forEach(x=>tc.removeChild(x));M.tembusan.forEach(t=>tc.appendChild(mkP(pr,t)))}}
 setIf(ps(rows2[L-1])[0],M.ttd);
 // lampiran
 setIf(ch[8],"KEPUTUSAN "+M.PU);setIf(ch[11],M.judul);setIf(ch[14],"SUSUNAN DAN KEANGGOTAAN\n"+M.namaUp);
 const hP=ch[15].cloneNode(true),gP=ch[17].cloneNode(true),tA=ch[16].cloneNode(true),tB=ch[19].cloneNode(true),tC=ch[31].cloneNode(true),endA=ch[35];
 ch.slice(15,35).forEach(e=>body.removeChild(e));
 const mkTbl=(proto,fill)=>{const t=proto.cloneNode(true),tr=kids(t,"tr"),head=tr[0];const pr={row:tr[tr.length-1].cloneNode(true),grp:tr[1].cloneNode(true)};tr.slice(1).forEach(r=>t.removeChild(r));fill(t,pr);return t};
 const addRow=(t,proto,vals)=>{const r=proto.cloneNode(true);kids(r,"tc").forEach((c,i)=>setCell(c,vals[i]??""));t.appendChild(r)};
 M.lamp.forEach((s,i)=>{const h=hP.cloneNode(true);setText(h,s.title);body.insertBefore(h,endA);
  let t;if(s.type==="A")t=mkTbl(tA,(t,pr)=>s.rows.forEach((r,j)=>addRow(t,pr.row,[String(j+1),...r])));
  else if(s.type==="C")t=mkTbl(tC,(t,pr)=>s.rows.forEach((r,j)=>addRow(t,pr.row,[String(j+1),...r])));
  else{const gProto=kids(tB,"tr")[1],rProto=kids(tB,"tr")[2];t=mkTbl(tB,()=>{});let n=0;s.groups.forEach(g=>{addRow(t,gProto,[g.es1]);g.rows.forEach(r=>addRow(t,rProto,[String(++n),...r]))})}
  body.insertBefore(t,endA);if(i<M.lamp.length-1)body.insertBefore(gP.cloneNode(true),endA)});
 const sg=kids(ch[37],"tr");setIf(kids(kids(sg[0],"tc")[1],"p")[0],M.signLine+",");setIf(kids(kids(sg[3],"tc")[2],"p")[0],M.ttd);
 let out=new XMLSerializer().serializeToString(doc);if(!out.startsWith("<?xml"))out='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'+out;
 numXml=numXml.replace(/(<w:num w:numId="\d+"[^>]*>[\s\S]*?<\/w:num>)(?![\s\S]*<w:num )/,`$1${newNums.join("")}`);
 zip.file("word/document.xml",out);zip.file("word/numbering.xml",numXml);
 return zip.generateAsync({type:"blob",mimeType:"application/vnd.openxmlformats-officedocument.wordprocessingml.document"})}

async function saveFile(filename,blob){
 try{const dl=window.claude&&await window.claude.use("downloads");if(dl){await dl.save({filename,data:blob});return true}}catch(e){if(e&&/declin|cancel|reject/i.test(String(e.message||e)))return false}
 const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();a.remove();return true}
async function dlWord(u){try{toast("Menyusun dokumen Word…");const b=await buildDocx(u);await saveFile(`Draft_SK_Tim_${u.kode}.docx`,b);toast("Draft SK (.docx) siap — format mengikuti KEP Tim Mekanisme Kerja")}catch(e){toast("Gagal menyusun Word: "+e.message)}}

