const SJ_="Sekretariat Jenderal",DJA_="Direktorat Jenderal Anggaran",BPPK_="Badan Pendidikan dan Pelatihan Keuangan",IJ_="Inspektorat Jenderal",DJP_="Direktorat Jenderal Pajak",DJPB_="Direktorat Jenderal Perbendaharaan",
 DJSEF_="Direktorat Jenderal Strategi Ekonomi dan Fiskal",DJPK_="Direktorat Jenderal Perimbangan Keuangan",DJPPR_="Direktorat Jenderal Pengelolaan Pembiayaan dan Risiko",DJSPSK_="Direktorat Jenderal Stabilitas dan Pengembangan Sektor Keuangan";
