/* ---------- generate slot dari alokasi ---------- */
function generate(u,note){const old=u.slots||[];const slots=[];const touched=new Set();
 u.komp.forEach(k=>k.alloc.forEach(a=>a.keds.forEach((ked,i)=>{const prev=old.find(s=>s.kid===k.id&&s.unit===a.unit&&s.idx===i);
  const pim=k.tipe==="pimpinan";const base=pim?{jenis:"jabatan",nama:"",nip:"",jab:a.isi?.[i]?.jab||"",satker:a.isi?.[i]?.satker||""}:{jenis:"jabatan",nama:"",nip:"",jab:"",satker:""};
  const s=Object.assign({id:nid(),kid:k.id,unit:a.unit,idx:i,ked,byCMO:pim},base,prev&&!pim?{jenis:prev.jenis,nama:prev.nama,nip:prev.nip,jab:prev.jab,satker:prev.satker}:{});
  if(prev&&prev.ked!==ked)touched.add(a.unit);slots.push(s)})));
 // unit yang jumlah slotnya berubah
 const cnt=(L,un)=>L.filter(s=>s.unit===un&&!s.byCMO).length;
 const units=[...new Set(slots.filter(s=>!s.byCMO).map(s=>s.unit))];
 units.forEach(un=>{if(old.length&&cnt(old,un)!==cnt(slots,un))touched.add(un)});
 const U={};units.forEach(un=>{const p=u.units[un];U[un]=p?{...p}:{status:"belum",sentAt:null,remind:[]};if(touched.has(un)&&U[un].status==="terkirim"){U[un].status="draft";U[un].sentAt=null}});
 u.slots=slots;u.units=U;const v=(u.versions.length||0)+1;u.versions.push({v,at:new Date().toISOString(),by:actor(),note:note||(v===1?"Generate pertama":"Revisi struktur")+` · ${slots.length} slot · ${units.length} unit`});
 if(u.status==="rancang")u.status="pengisian";u.revisi=false;
 addLog(u,v===1?`Struktur di-generate (v1): ${slots.length} slot untuk ${units.length} unit. Unit mendapat notifikasi.`:`Revisi struktur v${v}.${touched.size?` Unit terdampak: ${[...touched].map(sh).join(", ")} (perlu kirim ulang).`:""}`);
 return touched}

