 const au=$("#addU");if(au)au.onchange=()=>{if(!au.value)return;const k=u.komp.find(x=>x.tipe==="unit")||u.komp.find(x=>x.tipe!=="pimpinan");if(k)k.alloc.push({unit:au.value,keds:["Anggota"]});rr()};
 const ak=$("#addK");if(ak)ak.onchange=()=>{let v=ak.value;if(!v)return;if(v==="__c"){openM("Komponen lain",`<div class="f"><label>Nama komponen</label><input id="kN" placeholder="mis. Pengelola Komunikasi dan Pelatihan"></div><div class="f"><label>Tingkat</label><select id="kT"><option value="kemenkeu">${TIPE.kemenkeu}</option><option value="unit">${TIPE.unit}</option></select></div><div style="text-align:right"><button class="btn pri" id="kOk">Tambah</button></div>`);$("#kOk").onclick=()=>{const n=$("#kN").value.trim();if(!n)return;u.komp.push({id:nid(),label:n,tipe:$("#kT").value,tugas:[],alloc:[{unit:BT,keds:["Anggota"]}]});save();closeM();renderDetail()};return}
  u.komp.push(K(v,/Unit Eselon I/.test(v)?"unit":"kemenkeu",[{unit:/Teknis/.test(v)?u.owner:BT,keds:["Ketua","Anggota"]}]));rr()};
