   const jenis=/^nama/i.test(String(r[4]))?"nama":"jabatan",nip=String(r[5]).replace(/\D/g,""),v={jenis,nip,nama:String(r[6]).trim(),jab:String(r[7]).trim(),satker:String(r[8]).trim()};
